compile.workshop:
settings
{
	modes
	{
		Deathmatch
		{
			Score To Win: 9
		}
	}
}

variables {
    global:
        0: g
}

rule ("probe") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(g, 1);
    }
}

